var getModifiedArray = function(length, updates) {
    const diff = new Array(length + 1).fill(0);
    for (const [s, e, inc] of updates) {
        diff[s] += inc;
        diff[e + 1] -= inc;
    }
    const res = new Array(length);
    let running = 0;
    for (let i = 0; i < length; i++) {
        running += diff[i];
        res[i] = running;
    }
    return res;
};
